export class TerrainPass extends GenPass {
	constructor() {
		super(GenPassNameID.Terrain, 449.3721923828125);
	}

	ApplyPass(progress: Progress, configuration: GameConfiguration): void {
		let num: number = configuration.Get('FlatBeachPadding');
		progress.Message = $text[0].Value;
		let terrainFeatureType: number = 0;
		let num2: number = 0;
		let num3: number = Main.maxTilesY * 0.3;
		num3 *= GenBase._random.Next_Int32_Int32(90, 110) * 0.005;
		let num4: number = num3 + Main.maxTilesY * 0.2;
		num4 *= GenBase._random.Next_Int32_Int32(90, 110) * 0.01;
		if (WorldGen.remixWorldGen) {
			num4 = Main.maxTilesY * 0.5;
			if (Main.maxTilesX > 2500) {
				num4 = Main.maxTilesY * 0.6;
			}
			num4 *= GenBase._random.Next_Int32_Int32(95, 106) * 0.01;
		}
		let num5: number = num3;
		let num6: number = num3;
		let num7: number = num4;
		let num8: number = num4;
		if (WorldGen_SecretSeed.noSurface.Enabled) {
			num3 = 25;
			num4 = Main.maxTilesY * 0.4;
			num4 *= GenBase._random.Next_Int32_Int32(90, 110) * 0.01;
		}
		let num9: number = Main.maxTilesY * 0.23;
		let surfaceHistory: TerrainPass_SurfaceHistory = new TerrainPass_SurfaceHistory(500);
		num2 = (GenVars.leftBeachEnd + num) | 0;
		for (let i: number = 0; i < Main.maxTilesX; i++) {
			progress.Set(i / Main.maxTilesX);
			num5 = Math.min(num3, num5);
			num6 = Math.max(num3, num6);
			num7 = Math.min(num4, num7);
			num8 = Math.max(num4, num8);
			if (num2 <= 0) {
				terrainFeatureType = GenBase._random.Next_Int32_Int32(0, 5);
				num2 = GenBase._random.Next_Int32_Int32(5, 40);
				if (terrainFeatureType === 0) {
					num2 = Math.imul(num2, Math.trunc(GenBase._random.Next_Int32_Int32(5, 30) * 0.2) | 0);
				}
			}
			num2--;
			if (
				i > Main.maxTilesX * 0.45 &&
				i < Main.maxTilesX * 0.55 &&
				(terrainFeatureType === 3 || terrainFeatureType === 4)
			) {
				terrainFeatureType = GenBase._random.Next_Int32(3);
			}
			if (i > Main.maxTilesX * 0.48 && i < Main.maxTilesX * 0.52) {
				terrainFeatureType = 0;
			}
			if (!WorldGen_SecretSeed.noSurface.Enabled) {
				num3 += TerrainPass.GenerateWorldSurfaceOffset(terrainFeatureType);
			}
			let num10: number = 0.17;
			let num11: number = 0.26;
			if (WorldGen_SecretSeed.surfaceIsInSpace.Enabled) {
				num11 = 0.2199999988079071;
			} else if (WorldGen.drunkWorldGen) {
				num10 = 0.15;
				num11 = 0.28;
			}
			if (WorldGen.GetWorldSize() === 0) {
				num10 += 0.02;
			}
			if (!WorldGen_SecretSeed.noSurface.Enabled) {
				if (i < ((GenVars.leftBeachEnd + num) | 0) || i > ((GenVars.rightBeachStart - num) | 0)) {
					num3 = Utils.Clamp_T_T_T(num3, Main.maxTilesY * num10, num9);
				} else if (num3 < Main.maxTilesY * num10) {
					num3 = Main.maxTilesY * num10;
					num2 = 0;
				} else if (num3 > Main.maxTilesY * num11) {
					num3 = Main.maxTilesY * num11;
					num2 = 0;
				}
			}
			while (GenBase._random.Next_Int32_Int32(0, 3) === 0) {
				num4 += GenBase._random.Next_Int32_Int32(-2, 3);
			}
			if (WorldGen_SecretSeed.noSurface.Enabled) {
				if (num4 < num3 + Main.maxTilesY * 0.35) {
					num4 += 1;
				}
				if (num4 > num3 + Main.maxTilesY * 0.45) {
					num4 -= 1;
				}
			} else if (WorldGen.remixWorldGen) {
				if (Main.maxTilesX > 2500) {
					if (num4 > Main.maxTilesY * 0.7) {
						num4 -= 1;
					}
				} else if (num4 > Main.maxTilesY * 0.6) {
					num4 -= 1;
				}
			} else {
				if (num4 < num3 + Main.maxTilesY * 0.06) {
					num4 += 1;
				}
				if (num4 > num3 + Main.maxTilesY * 0.35) {
					num4 -= 1;
				}
			}
			surfaceHistory.Record(num3);
			if (WorldGen_SecretSeed.surfaceIsInSpace.Enabled && !WorldGen_SecretSeed.noSurface.Enabled) {
				TerrainPass.FillColumn(i, num3 - Main.maxTilesY * 0.08, num4);
				continue;
			}
			TerrainPass.FillColumn(i, num3, num4);
			if (i === ((GenVars.rightBeachStart - num) | 0)) {
				if (num3 > num9) {
					TerrainPass.RetargetSurfaceHistory(surfaceHistory, i, num9);
				}
				terrainFeatureType = 0;
				num2 = (Main.maxTilesX - i) | 0;
			}
		}
		Main.worldSurface = Math.trunc(num6 + 25) | 0;
		if (WorldGen_SecretSeed.noSurface.Enabled) {
			Main.worldSurface = 25;
		}
		Main.rockLayer = num8;
		let num12: number = Math.imul(Math.trunc((Main.rockLayer - Main.worldSurface) / 6) | 0, 6);
		Main.rockLayer = Math.trunc(Main.worldSurface + num12) | 0;
		let num13: number =
			((((Math.trunc(Main.rockLayer + Main.maxTilesY) | 0) / 2) | 0) +
				GenBase._random.Next_Int32_Int32(-100, 20)) |
			0;
		let lavaLine: number = (num13 + GenBase._random.Next_Int32_Int32(50, 80)) | 0;
		if (WorldGen.remixWorldGen) {
			lavaLine = ((Math.trunc(Main.worldSurface * 4 + num4) | 0) / 5) | 0;
		}
		let num14: number = 20;
		if (num7 < num6 + num14) {
			let num15: number = (num7 + num6) / 2;
			let num16: number = Math.abs(num7 - num6);
			if (num16 < num14) {
				num16 = num14;
			}
			num7 = num15 + num16 / 2;
			num6 = num15 - num16 / 2;
		}
		GenVars.rockLayer = num4;
		GenVars.rockLayerHigh = num8;
		GenVars.rockLayerLow = num7;
		GenVars.worldSurface = num3;
		GenVars.worldSurfaceHigh = num6;
		GenVars.worldSurfaceLow = num5;
		GenVars.waterLine = num13;
		GenVars.lavaLine = lavaLine;
		GenVars.remixMushroomLayerLow = (Main.maxTilesY - 350) | 0;
		GenVars.remixMushroomLayerHigh = Main.UnderworldLayer;
		GenVars.remixSurfaceLayerLow = Math.trunc(GenVars.rockLayerLow) | 0;
		GenVars.remixSurfaceLayerHigh = GenVars.remixMushroomLayerLow;
	}

	static FillColumn(x: number, worldSurface: number, rockLayer: number): void {
		for (let i: number = 0; i < worldSurface; i++) {
			Rt.tile.get(x, i).active_Boolean(false);
			Rt.tile.get(x, i).frameX = -1;
			Rt.tile.get(x, i).frameY = -1;
		}
		for (let j: number = Math.trunc(worldSurface) | 0; j < Main.maxTilesY; j++) {
			if (j < rockLayer) {
				Rt.tile.get(x, j).active_Boolean(true);
				Rt.tile.get(x, j).type = 0;
				Rt.tile.get(x, j).frameX = -1;
				Rt.tile.get(x, j).frameY = -1;
			} else {
				Rt.tile.get(x, j).active_Boolean(true);
				Rt.tile.get(x, j).type = 1;
				Rt.tile.get(x, j).frameX = -1;
				Rt.tile.get(x, j).frameY = -1;
			}
		}
	}

	static RetargetColumn(x: number, worldSurface: number): void {
		for (let i: number = 0; i < worldSurface; i++) {
			Rt.tile.get(x, i).active_Boolean(false);
			Rt.tile.get(x, i).frameX = -1;
			Rt.tile.get(x, i).frameY = -1;
		}
		for (let j: number = Math.trunc(worldSurface) | 0; j < Main.maxTilesY; j++) {
			if (Rt.tile.get(x, j).type !== 1 || !Rt.tile.get(x, j).active_()) {
				Rt.tile.get(x, j).active_Boolean(true);
				Rt.tile.get(x, j).type = 0;
				Rt.tile.get(x, j).frameX = -1;
				Rt.tile.get(x, j).frameY = -1;
			}
		}
	}

	static GenerateWorldSurfaceOffset(featureType: number): number {
		let num: number = 0;
		if (
			(WorldGen.drunkWorldGen || WorldGen.getGoodWorldGen || WorldGen.remixWorldGen) &&
			WorldGen.genRand.Next_Int32(2) === 0
		) {
			switch (featureType) {
				case 0:
					while (GenBase._random.Next_Int32_Int32(0, 6) === 0) {
						num += GenBase._random.Next_Int32_Int32(-1, 2);
					}
					break;
				case 1:
					while (GenBase._random.Next_Int32_Int32(0, 3) === 0) {
						num -= 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 10) === 0) {
						num += 1;
					}
					break;
				case 2:
					while (GenBase._random.Next_Int32_Int32(0, 3) === 0) {
						num += 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 10) === 0) {
						num -= 1;
					}
					break;
				case 3:
					while (GenBase._random.Next_Int32_Int32(0, 3) !== 0) {
						num -= 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 6) === 0) {
						num += 1;
					}
					break;
				case 4:
					while (GenBase._random.Next_Int32_Int32(0, 3) !== 0) {
						num += 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 5) === 0) {
						num -= 1;
					}
					break;
			}
		} else {
			switch (featureType) {
				case 0:
					while (GenBase._random.Next_Int32_Int32(0, 7) === 0) {
						num += GenBase._random.Next_Int32_Int32(-1, 2);
					}
					break;
				case 1:
					while (GenBase._random.Next_Int32_Int32(0, 4) === 0) {
						num -= 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 10) === 0) {
						num += 1;
					}
					break;
				case 2:
					while (GenBase._random.Next_Int32_Int32(0, 4) === 0) {
						num += 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 10) === 0) {
						num -= 1;
					}
					break;
				case 3:
					while (GenBase._random.Next_Int32_Int32(0, 2) === 0) {
						num -= 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 6) === 0) {
						num += 1;
					}
					break;
				case 4:
					while (GenBase._random.Next_Int32_Int32(0, 2) === 0) {
						num += 1;
					}
					while (GenBase._random.Next_Int32_Int32(0, 5) === 0) {
						num -= 1;
					}
					break;
			}
		}
		return num;
	}

	static RetargetSurfaceHistory(
		history: TerrainPass_SurfaceHistory,
		targetX: number,
		targetHeight: number
	): void {
		for (let i: number = 0; i < ((history.Length / 2) | 0); i++) {
			if (history.get_Item((history.Length - 1) | 0) <= targetHeight) {
				break;
			}
			for (let j: number = 0; j < ((history.Length - Math.imul(i, 2)) | 0); j++) {
				let num: number = history.get_Item((((history.Length - j) | 0) - 1) | 0);
				num -= 1;
				history.set_Item((((history.Length - j) | 0) - 1) | 0, num);
				if (num <= targetHeight) {
					break;
				}
			}
		}
		for (let k: number = 0; k < history.Length; k++) {
			let worldSurface: number = history.get_Item((((history.Length - k) | 0) - 1) | 0);
			TerrainPass.RetargetColumn((targetX - k) | 0, worldSurface);
		}
	}
}

export class TerrainPass_SurfaceHistory {
	_heights: Float64Array = null!;

	_index: number = 0;

	get_Item(index: number): number {
		return this._heights[(((index + this._index) | 0) % this._heights.length) | 0];
	}

	set_Item(index: number, value: number) {
		this._heights[(((index + this._index) | 0) % this._heights.length) | 0] = value;
	}

	get Length(): number {
		return this._heights.length;
	}

	constructor(size: number) {
		this._heights = new Float64Array(size);
	}

	Record(height: number): void {
		this._heights[this._index] = height;
		this._index = (((this._index + 1) | 0) % this._heights.length) | 0;
	}
}

